readonly class UserProfile {
    public function __construct(
        public string $id,
        public string $email,
        public DateTimeImmutable $createdAt = new DateTimeImmutable()
    ) {}
}

$statusMessage = match ($httpStatusCode) {
    200, 201 => 'Operation Successful',
    400 => 'Bad Request',
    401, 403 => 'Unauthorized Access',
    404 => 'Resource Not Found',
    500 => 'Internal Server Error',
    default => 'Unhandled Status Code',
};

enum PaymentStatus: string {
    case Pending = 'pending';
    case Paid = 'paid';
    case Failed = 'failed';

    public function isFinal(): bool {
        return match($this) {
            self::Paid, self::Failed => true,
            self::Pending => false,
        };
    }
}

function chunkGenerator(iterable $items, int $size): Generator {
    $chunk = [];
    foreach ($items as $item) {
        $chunk[] = $item;
        if (count($chunk) === $size) {
            yield $chunk;
            $chunk = [];
        }
    }
    if (!empty($chunk)) yield $chunk;
}

function safeDivide(float $a, float $b): ?float {
    return abs($b) < PHP_FLOAT_EPSILON ? null : $a / $b;
}

final class Singleton {
    private static ?self $instance = null;
    private function __construct() {}
    public static function getInstance(): self {
        return self::$instance ??= new self();
    }
}
